      "physicalExam": "T: {t}℃ P: {p}次/分 R: {r}次/分 BP: {bp}mmHg\\n发育正常，营养中等，神志清楚，精神可，自主体位，查体合作。全身皮肤黏膜无黄染及出血点，浅表淋巴结未触及肿大。头颅无畸形，五官端正。双侧瞳孔等大等圆，对光反射灵敏。颈软，气管居中，甲状腺未触及肿大。胸廓无畸形。双肺呼吸音清，未闻及干湿性啰音。心脏及双下肢查体。腹平软，无压痛及反跳痛，肝脾肋下未触及，肠鸣音正常。病理征阴性。",
