        "variationAnalysis": "1.住院时间延长：\n   - 原因：溶栓后出现严重出血并发症（颅内出血、消化道大出血）需延长治疗；合并心力衰竭或心源性休克需长期监护；溶栓后再梗死需紧急转诊\n   - 依据《急性ST段抬高型心肌梗死诊断和治疗指南（2019）》：溶栓治疗颅内出血发生率约0.5%-1%，需立即停用溶栓及抗凝药物并紧急处理\n2.治疗方案变更：\n   - 原因：溶栓禁忌（近期出血史、颅内出血史、主动脉夹层等）无法溶栓需直接转诊PCI；溶栓失败需补救性PCI；出现室颤/室速需电除颤或抗心律失常药物\n   - 依据《急性ST段抬高型心肌梗死诊断和治疗指南（2019）》：溶栓失败（90分钟内ST段回落<50%）应立即行补救性PCI\n3.转诊指征：\n   - 所有溶栓后患者均应在24小时内转上级医院行冠脉造影；溶栓失败者立即转诊行补救性PCI；心源性休克需IABP或ECMO支持；疑似机械并发症（室间隔穿孔、乳头肌断裂、心脏破裂）需紧急外科手术\n   - 依据《急性ST段抬高型心肌梗死诊断和治疗指南（2019）》及《中国急性ST段抬高型心肌梗死直接PCI专家共识》：溶栓后24小时内常规转运PCI是标准流程",
