        "variationAnalysis": "1.住院时间延长：\n   - 原因：溶栓后出血转化需延长监护及治疗；大面积脑梗死伴脑水肿需脱水降颅压甚至去骨瓣减压；合并吸入性肺炎、泌尿系感染等需延长抗感染治疗；神经功能恢复缓慢需延长康复\n   - 依据《中国急性缺血性脑卒中诊治指南（2018）》：溶栓后症状性颅内出血发生率约2%-7%，需立即停药并紧急处理\n2.治疗方案变更：\n   - 原因：超时间窗（4.5-6h）或有取栓指征需转上级医院行血管内取栓；溶栓后出血转化需停用溶栓及抗血小板药物；发现房颤需改为抗凝治疗（华法林或新型口服抗凝药）\n   - 依据《中国急性缺血性脑卒中诊治指南（2018）》：大血管闭塞且符合取栓指征者应转运上级医院行机械取栓（发病6-24h内，需影像评估）\n3.转诊指征：\n   - 大血管闭塞需机械取栓（发病6-24h内，CT灌注评估有可挽救脑组织）；大面积脑梗死需去骨瓣减压术；溶栓后症状性颅内出血需神经外科评估；需介入治疗颈动脉狭窄或动脉瘤；病情恶化需神经重症监护\n   - 依据《中国急性缺血性脑卒中诊治指南（2018）》及《中国脑血管病一级预防指南》：符合取栓指征者应尽快转运至有血管内治疗能力的上级医院",
