      "physicalExam": "T: {t}℃ P: {p}次/分 R: {r}次/分 BP: {bp}mmHg\\n发育正常。全身皮肤黏膜无黄染。心界不大，各瓣膜区未闻及病理性杂音。双肺呼吸音清，未闻及干湿性啰音。腹平软，无压痛及反跳痛，肝脾肋下未触及。内分泌代谢等专科查体详见下述。",
      "specialistExam": "内分泌科专科检查：神志清晰，生命体征平稳。胸廓对称无畸形，双肺听诊呼吸音清，未闻及干湿性啰音及胸膜摩擦音。心界不大，心率80次/分，心律齐，瓣膜听诊区无病理性杂音。腹部平软，无压痛及反跳痛，肝脾肋下未触及。双下肢无凹陷性水肿，生理反射存在，病理反射未引出。",
      "auxiliaryExam": "{date} 血常规：WBC {wbc}×10^9/L, Hb {hb}g/L, Plt {plt}×10^9/L。\n{date} 生化全套：肝肾功能（肌酐 {cr}μmol/L）、电解质（钾 {k}mmol/L, 钠 {na}mmol/L）基本正常。\n{date} 专科影像及功能检查：心电图/胸片/超声等均支持\"2型糖尿病伴酮症酸中毒\"临床诊断。",
      "admitDiagnosis": "1、2型糖尿病伴酮症酸中毒\n2、原发性高血压 3级（极高危）",
