      "auxiliaryExam": "{date} 血常规：WBC {wbc}×10^9/L, Hb {hb}g/L, Plt {plt}×10^9/L。\n{date} 生化全套：肝肾功能（肌酐 {cr}μmol/L）、电解质（钾 {k}mmol/L, 钠 {na}mmol/L）基本正常。\n{date} 专科影像及功能检查：心电图/胸片/超声等均支持\"间质性肺疾病\"临床诊断。",
      "admitDiagnosis": "1、间质性肺疾病\n2、原发性高血压 3级（极高危）",
