        "treatmentOptions": "1.氧疗：低流量持续吸氧（FiO2 28%-30%），目标SpO2 88%-92%\n2.无创正压通气（BiPAP）：Ⅱ型呼衰经氧疗不能纠正CO2潴留时使用\n3.抗感染、支气管扩张剂、糖皮质激素、祛痰治疗\n4.并发症防治：肺性脑病、肺源性心脏病、消化道出血",
