        "medicationPlan": "1.抗感染：头孢哌酮舒巴坦3g静脉滴注每日2次，联合左氧氟沙星0.5g静脉滴注每日1次\n2.解痉平喘：异丙托溴铵2ml+沙丁胺醇2.5mg雾化吸入每日2次\n3.糖皮质激素：甲泼尼龙40mg静脉滴注每日1次，3-5天递减\n4.祛痰：盐酸氨溴索30mg静脉注射每日2次\n5.维持治疗：布地奈德福莫特罗160/4.5μg吸入每日2次、噻托溴铵18μg吸入每日1次",
