      "presentIllness": "患者{days}天前受凉后出现阵发性咳嗽，初为干咳，后渐咳白粘痰，量少，不易咳出，{fdays}天前出现发热，体温最高{tmax}℃，伴咽痛、鼻塞、流涕，无胸痛，无咯血，无呼吸困难，无夜间盗汗。自行口服\"感冒药\"及\"阿莫西林\"治疗，症状无明显好转，遂至我院门诊就诊，查血常规提示白细胞升高，胸部X线检查未见明显异常，为进一步诊治，遂拟\"急性支气管炎\"收入院。患者近期精神可，食欲下降，睡眠欠佳，二便正常，体重无明显变化。",
