        "medicationPlan": "1.抗感染：头孢呋辛1.5g静脉滴注每日2次，好转后改头孢呋辛酯0.5g口服每日2次\n2.祛痰：盐酸氨溴索30mg每日3次口服\n3.镇咳：复方甘草合剂10ml每日3次口服（剧烈干咳者）\n4.解热：对乙酰氨基酚0.5g必要时口服（体温>38.5℃）",
