        "examRequired": "血常规、尿常规、生化全套、肿瘤标志物（CEA、CYFRA21-1、NSE）、胸部低剂量螺旋CT",
        "examOptional": "胸部增强CT、PET-CT、T-SPOT.TB、支气管镜或经皮肺穿刺活检、肺功能",
        "medicationPlan": "1.随访观察为主，无需特殊药物治疗\n2.合并呼吸道感染者：抗感染治疗（头孢呋辛等）\n3.确诊恶性者：手术/放化疗/靶向治疗（参照肺癌路径）",
        "surgeryDay": "非手术治疗",
