        "treatmentOptions": "1.病因治疗：抗感染（重症肺炎者）、控制原发病\n2.氧疗：鼻导管→面罩→经鼻高流量氧疗（HFNC）→无创通气→有创机械通气\n3.肺保护性通气策略：小潮气量（6ml/kg理想体重）、平台压≤30cmH2O\n4.限制液体入量、营养支持、防治多器官功能障碍",
        "standardLOS": "10-14天",
        "entryCriteria": "第一诊断符合ICD-10：J80，氧合指数>200mmHg，无严重危重合并症，适合路径管理",
        "examRequired": "血常规、尿常规、生化全套、动脉血气分析、胸部CT、血培养、痰培养+药敏、BNP、心电图",
        "examOptional": "超声心动图、D-二聚体、肺动脉CTA（排除肺栓塞）、炎症指标（PCT、IL-6）、肺顺应性监测",
        "medicationPlan": "1.抗感染：哌拉西林他唑巴坦4.5g静脉滴注每8小时1次，联合左氧氟沙星0.5g静脉滴注每日1次\n2.糖皮质激素：甲泼尼龙40mg静脉滴注每日1次（ARDS伴顽固低氧者短期使用）\n3.祛痰：盐酸氨溴索30mg静脉注射每日2次\n4.镇痛镇静（机械通气时）：右美托咪定或丙泊酚\n5.营养支持：早期肠内营养，控制血糖",
