        "treatmentOptions": "1.抗感染治疗：依据血培养及药敏选择敏感抗生素，足量长程（4-6周）静脉给药\n2.经验治疗：草绿色链球菌首选青霉素G联合庆大霉素；肠球菌选用青霉素+庆大霉素/链霉素；MRSA选用万古霉素\n3.外科治疗：赘生物致难治性心衰、反复栓塞、脓肿、感染不能控制者行瓣膜置换术",
