        "medicationPlan": "1.草绿色链球菌：青霉素G 400万U静脉滴注每4小时1次，联合庆大霉素1mg/kg静脉滴注每8小时1次，疗程4周\n2.青霉素过敏者：万古霉素1g静脉滴注每12小时1次，疗程4周\n3.心衰治疗：呋塞米20mg口服每日1次、培哚普利2mg口服每日1次\n4.监测：血培养每周复查至连续阴性，监测肝肾功能及耳毒性",
