      "auxiliaryExam": "{date} 血常规：WBC {wbc}×10^9/L, Hb {hb}g/L, Plt {plt}×10^9/L。\n{date} 生化全套：肝肾功能（肌酐 {cr}μmol/L）、电解质（钾 {k}mmol/L, 钠 {na}mmol/L）基本正常，甲状腺功能正常。\n{date} 心电图：窦性心动过缓，心率{hr}次/分，频发房性早搏。\n{date} 24小时动态心电图：平均心率{p_avg}次/分，最慢心率{p_min}次/分，窦性停搏最长{sa}秒，可见短阵房性心动过速，运动后心率不能相应增快（固有心率低下）。",
