        "diagnosticBasis": "1.临床表现：乏力、食欲减退、腹胀、黄疸，可有肝区不适\n2.体征：慢性肝病面容、皮肤巩膜黄染、肝大压痛、肝掌蜘蛛痣\n3.辅助检查：HBsAg阳性>6个月；肝功能异常（ALT/AST升高）；HBV-DNA阳性提示病毒复制；肝组织学或影像学提示肝脏炎症/纤维化",
        "treatmentOptions": "1.抗病毒治疗：恩替卡韦、替诺福韦（TDF）、丙酚替诺福韦（TAF）等核苷（酸）类似物长期口服；干扰素α/Peg-IFNα\n2.保肝降酶：复方甘草酸苷、水飞蓟宾、双环醇等\n3.监测随访：每3-6个月复查肝功能、HBV-DNA、AFP、腹部彩超\n4.肝硬化及肝癌并发症的筛查与防治",
        "standardLOS": "7-14天",
        "entryCriteria": "第一诊断符合ICD-10：B18.1，无严重危重合并症（失代偿、肝衰竭），适合路径管理",
        "examRequired": "血常规、尿常规、生化全套（肝功能）、凝血功能、乙肝两对半、HBV-DNA定量、AFP、腹部彩超、甲肝戊肝抗体",
        "examOptional": "肝脏瞬时弹性扫描（FibroScan）、肝脏穿刺活检、自身抗体（ANA/SMA）、免疫球蛋白、乙肝病毒耐药基因检测、HBsAg定量",
        "medicationPlan": "1.恩替卡韦0.5mg口服每日1次（初治首选，强效低耐药）\n2.替诺福韦（TDF）300mg口服每日1次或丙酚替诺福韦（TAF）25mg口服每日1次（备选）\n3.保肝：复方甘草酸苷片50mg口服每日3次；水飞蓟宾70mg口服每日3次\n4.疗程：长期口服，HBeAg阳性者建议治疗至HBeAg血清学转换后继续巩固至少1年",
