      "physicalExam": "T: {t}℃ P: {p}次/分 R: {r}次/分 BP: {bp}mmHg\\n发育正常，营养中等，神志清楚，精神可，自主体位，查体合作。全身皮肤黏膜无黄染及出血点，浅表淋巴结未触及肿大。头颅无畸形，双侧瞳孔等大等圆，对光反射灵敏。颈软，气管居中，甲状腺未触及肿大。胸廓对称，双肺呼吸音清，未闻及干湿啰音。心界不大，心率{hr}次/分，律齐，各瓣膜区未闻及病理性杂音。腹部平软，上腹部轻压痛，无反跳痛，肝脾肋下未触及，未触及腹部包块，肠鸣音正常。双下肢无水肿，生理反射存在，病理征阴性。",
      "specialistExam": "消化内科专科检查：腹部平软，无胃肠型及蠕动波，上腹部轻压痛，无反跳痛及肌紧张，肝脾肋下未触及，腹部未触及包块，肝区及肾区无叩击痛，移动性浊音（-），肠鸣音正常。",
      "auxiliaryExam": "{date} 血常规：WBC {wbc}×10^9/L, Hb {hb}g/L, Plt {plt}×10^9/L。\n{date} 生化全套：肝肾功能（肌酐 {cr}μmol/L）、电解质（钾 {k}mmol/L, 钠 {na}mmol/L）基本正常。\n{date} 胃镜：慢性非萎缩性胃炎（轻度），幽门螺杆菌检测阴性。\n{date} 腹部彩超：肝胆胰脾未见明显异常。",
