        "treatmentOptions": "1.生活方式及心理干预：少食多餐、清淡饮食、规律作息、心理疏导\n2.促动力药物：多潘立酮、莫沙必利（餐后不适综合征）\n3.抑酸药物：PPI（上腹痛综合征）\n4.根除幽门螺杆菌（阳性者）；消化酶辅助\n5.合并焦虑抑郁者：抗焦虑/抗抑郁药物（氟哌噻吨美利曲辛等）",
        "standardLOS": "5-7天",
        "entryCriteria": "第一诊断符合ICD-10：K30，符合罗马IV诊断标准，无报警症状（消瘦、黑便、呕血、贫血等），适合路径管理",
        "examRequired": "血常规、尿常规、便常规+潜血、生化全套、胃镜、幽门螺杆菌检测（尿素呼气试验）、腹部彩超",
        "examOptional": "腹部CT、钡餐造影、胃排空功能测定、心理量表评估（SAS/SDS）、食物过敏原检测",
        "medicationPlan": "1.促动力：莫沙必利5mg口服每日3次餐前（或多潘立酮10mg每日3次餐前）\n2.抑酸：奥美拉唑20mg口服每日1-2次\n3.消化酶：复方消化酶胶囊1粒口服每日3次餐后\n4.心理干预：氟哌噻吨美利曲辛片10.5mg口服每日1次（焦虑明显者）\n5.疗程：4-8周，症状缓解后逐渐减量",
