        "diagnosticBasis": "1.罗马IV标准：反复腹痛，近3个月平均每周至少1天，伴排便频率及性状改变，诊断前症状至少6个月\n2.典型表现：腹痛排便后缓解，腹泻便秘交替，黏液便，腹胀，情绪及饮食诱发\n3.排除器质性病变：结肠镜正常，便常规及培养阴性，无消瘦、贫血、便血等报警症状",
        "treatmentOptions": "1.生活方式调整：低FODMAP饮食、规律作息、适度运动、压力管理\n2.解痉止痛：匹维溴铵（腹痛明显者）\n3.止泻：蒙脱石散、洛哌丁胺（腹泻型）；缓泻剂：乳果糖（便秘型）\n4.调节菌群：益生菌（双歧杆菌、乳酸杆菌）\n5.心理干预：抗焦虑/抑郁药物（氟哌噻吨美利曲辛、SSRI）",
        "standardLOS": "5-7天",
        "entryCriteria": "第一诊断符合ICD-10：K58.9，符合罗马IV标准，无报警症状（便血、消瘦、贫血、夜间症状），适合路径管理",
        "examRequired": "血常规、尿常规、便常规+潜血、便培养、生化全套、结肠镜、腹部彩超",
        "examOptional": "甲状腺功能、乳糖氢呼气试验、食物过敏原检测、腹部CT、心理量表评估（SAS/SDS）、肛门直肠测压",
