      "physicalExam": "T: {t}℃ P: {p}次/分 R: {r}次/分 BP: {bp}mmHg\\n发育正常，营养中等，神志清楚，精神差，自主体位，查体合作。全身皮肤可见多处抓痕及色素沉着，皮肤巩膜中度黄染，浅表淋巴结未触及肿大。头颅无畸形，双侧瞳孔等大等圆，对光反射灵敏。颈软，气管居中，甲状腺未触及肿大。胸廓对称，双肺呼吸音清，未闻及干湿啰音。心界不大，心率{hr}次/分，律齐，各瓣膜区未闻及病理性杂音。腹平软，无压痛及反跳痛，肝脏肋下约2cm，质硬，无压痛，脾肋下约2cm，移动性浊音（-），肠鸣音正常。眼睑及四肢关节伸侧可见黄色瘤，双下肢无水肿，生理反射存在，病理征阴性。",
