        "treatmentOptions": "1.一线治疗：熊去氧胆酸（UDCA）13-15mg/(kg·d)，长期服用\n2.二线治疗：UDCA应答不佳者加用奥贝胆酸（OCA）或贝特类\n3.对症治疗：考来烯胺（瘙痒）、补充脂溶性维生素、骨质疏松防治\n4.终末期：肝移植评估（肝硬化失代偿期）",
