        "examOptional": "肝脏穿刺活检、肝脏瞬时弹性扫描、抗核抗体谱、甲状腺功能、骨密度、胃镜（食管静脉曲张）、p-ANCA",
        "medicationPlan": "1.熊去氧胆酸250mg口服每日3次（13-15mg/(kg·d)），长期服用\n2.瘙痒：考来烯胺4g口服每日3次（与UDCA间隔2小时以上服用）\n3.补充脂溶性维生素：维生素A 5000IU每日1次、维生素D3 800IU每日1次、维生素E、维生素K\n4.骨质疏松：钙剂600mg每日1次、阿法骨化醇0.25μg每日1次\n5.UDCA应答不佳者：加用奥贝胆酸5-10mg每日1次",
