      "pastHistory": "否认\"高血压、糖尿病\"病史。否认\"肝炎\"、\"结核\"史，否认手术史、外伤史、输血史。否认食物及药物过敏史。",
      "personalHistory": "原地出生，否认长期外地居住史。不吸烟，不饮酒。无特殊职业暴露史。",
