      "physicalExam": "T: {t}℃ P: {p}次/分 R: {r}次/分 BP: {bp}mmHg\\n发育正常，营养中等，神志清楚，精神可，自主体位，查体合作。全身皮肤黏膜无黄染及出血点，浅表淋巴结未触及肿大。头颅无畸形，双侧瞳孔等大等圆，对光反射灵敏。颈软，气管居中，甲状腺未触及肿大。胸廓对称，双肺呼吸音清，未闻及干湿啰音。心界不大，心率{hr}次/分，律齐，各瓣膜区未闻及病理性杂音。腹平软，无压痛及反跳痛，肝脾肋下未触及，双肾区无叩击痛，输尿管行程无压痛，肠鸣音正常。双下肢无水肿，生理反射存在，病理征阴性。",
      "specialistExam": "肾脏内科专科检查：腹平软，无压痛及反跳痛，肝脾肋下未触及，双肾区无叩击痛，双侧输尿管行程无压痛，移动性浊音（-），双下肢无凹陷性水肿。",
      "auxiliaryExam": "{date} 血常规：WBC {wbc}×10^9/L, Hb {hb}g/L, Plt {plt}×10^9/L。\n{date} 尿常规：蛋白 {up}，潜血（-），尿糖 {ug}，比重 {usg}。\n{date} 生化全套：血肌酐 {cr}μmol/L、尿素氮 {bun}mmol/L、钾 {k}mmol/L、钠 {na}mmol/L、氯 {cl}mmol/L、碳酸氢根 {hco3}mmol/L、白蛋白 {alb}g/L。\n{date} 24小时尿蛋白定量：{u24}g/24h（少量）。\n{date} 泌尿系彩超：双肾大小正常或轻度缩小，皮质回声增强，皮髓质界限欠清。",
      "admitDiagnosis": "1、慢性间质性肾炎\n2、慢性肾脏病 2期",
