        "treatmentOptions": "1.立即停用可疑药物（NSAIDs等），去除病因\n2.纠正水、电解质及酸碱平衡紊乱（纠酸、补液）\n3.控制血压（ACEI/ARB）延缓肾功能进展\n4.避免肾毒性药物，定期随访肾功能",
