        "examOptional": "肾穿刺活检（诊断不明或肾功能进行性恶化者）、自身抗体及免疫球蛋白（排除自身免疫性间质性肾炎）、结石及代谢相关检查",
        "medicationPlan": "1.停用NSAIDs等可疑药物，避免肾毒性药物及造影剂\n2.纠正酸中毒：碳酸氢钠1.0g口服每日3次（根据血气调整）\n3.纠正电解质紊乱：补钾/限钾、补钠等对症处理\n4.控制血压：缬沙坦80mg口服每日1次（或贝那普利10mg每日1次），目标血压<130/80mmHg\n5.充分水化，每日饮水2000ml以上",
